-- 138: Final exact-set and relationship guard for WASSCE expansion beta batch 001.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_138_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_138_guard;
INSERT INTO _migration_138_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id JOIN syllabus_topics st ON st.id = q.syllabus_topic_id JOIN subject_specifications ss ON ss.id = st.specification_id JOIN question_content_releases r ON r.question_id = q.id WHERE q.id IN ('q_was_irs_b001_001', 'q_was_irs_b001_002', 'q_was_irs_b001_003', 'q_was_irs_b001_004', 'q_was_irs_b001_005', 'q_was_irs_b001_006', 'q_was_irs_b001_007', 'q_was_irs_b001_008', 'q_was_irs_b001_009', 'q_was_irs_b001_010', 'q_was_irs_b001_011', 'q_was_irs_b001_012', 'q_was_irs_b001_013', 'q_was_irs_b001_014', 'q_was_irs_b001_015', 'q_was_irs_b001_016', 'q_was_irs_b001_017', 'q_was_irs_b001_018', 'q_was_irs_b001_019', 'q_was_irs_b001_020', 'q_was_irs_b001_021', 'q_was_irs_b001_022', 'q_was_irs_b001_023', 'q_was_irs_b001_024', 'q_was_irs_b001_025', 'q_was_irs_b001_026', 'q_was_irs_b001_027', 'q_was_irs_b001_028', 'q_was_irs_b001_029', 'q_was_irs_b001_030', 'q_was_irs_b001_031', 'q_was_irs_b001_032', 'q_was_irs_b001_033', 'q_was_irs_b001_034', 'q_was_irs_b001_035', 'q_was_irs_b001_036', 'q_was_irs_b001_037', 'q_was_irs_b001_038', 'q_was_irs_b001_039', 'q_was_irs_b001_040', 'q_was_elect_b001_001', 'q_was_elect_b001_002', 'q_was_elect_b001_003', 'q_was_elect_b001_004', 'q_was_elect_b001_005', 'q_was_elect_b001_006', 'q_was_elect_b001_007', 'q_was_elect_b001_008', 'q_was_elect_b001_009', 'q_was_elect_b001_010', 'q_was_elect_b001_011', 'q_was_elect_b001_012', 'q_was_elect_b001_013', 'q_was_elect_b001_014', 'q_was_elect_b001_015', 'q_was_elect_b001_016', 'q_was_elect_b001_017', 'q_was_elect_b001_018', 'q_was_elect_b001_019', 'q_was_elect_b001_020', 'q_was_elect_b001_021', 'q_was_elect_b001_022', 'q_was_elect_b001_023', 'q_was_elect_b001_024', 'q_was_elect_b001_025', 'q_was_elect_b001_026', 'q_was_elect_b001_027', 'q_was_elect_b001_028', 'q_was_elect_b001_029', 'q_was_elect_b001_030', 'q_was_elect_b001_031', 'q_was_elect_b001_032', 'q_was_elect_b001_033', 'q_was_elect_b001_034', 'q_was_elect_b001_035', 'q_was_elect_b001_036', 'q_was_elect_b001_037', 'q_was_elect_b001_038', 'q_was_elect_b001_039', 'q_was_elect_b001_040') AND q.subject_id = t.subject_id AND q.subject_id = ss.subject_id AND q.exam_type_id = ss.exam_type_id AND q.exam_board_id = ss.exam_board_id AND q.question_type = 'multiple_choice' AND json_valid(q.options) AND json_array_length(q.options) = 4 AND q.correct_answer IN ('A','B','C','D') AND length(q.explanation) >= 80 AND r.batch_id = 'wassce-expansion-beta-001' AND r.quality_assurance = 'automated_beta' AND r.release_channel = 'beta' AND r.official_exam_board_content = 0 AND r.feedback_enabled = 1) = 80 AND (SELECT COUNT(*) FROM question_content_releases WHERE batch_id = 'wassce-expansion-beta-001') = 80 THEN 1 ELSE 0 END;
DROP TABLE _migration_138_guard;
